import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"三路快排","description":"","frontmatter":{"title":"三路快排","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quicksort-3way.md","filePath":"cs/quicksort-3way.md","lastUpdated":1789023840000}'),h={name:"cs/quicksort-3way.md"};function _(u,a,B,m,E,q){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="三路快排" tabindex="-1">三路快排 <a class="header-anchor" href="#三路快排" aria-label="Permalink to &quot;三路快排&quot;">​</a></h1><div class="epigraph"><p>等于轴的键一次聚成中段；左右只递归严格小于与严格大于，重复键不再把分区退化成单侧。</p><footer>—— 据 Dijkstra, A Discipline of Programming, 1976；Bentley and McIlroy, Engineering a Sort Function, 1993；CLRS 第 7 章整理</footer></div><p>上一课<a href="/cs/quicksort-expected">快排与期望</a>给出随机两路分区：小于左、大于右，等于键落在哪一侧未规定。大量重复时，两路把等于轴的键仍丢进递归，最坏可接近平方。本课不重做指示器分析。缺口是<strong>三路分区</strong>：小于 / 等于 / 大于，中段钉死，只递归两端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两路 <code>partition</code> 的不变式通常是「左侧 $\\lt $ 轴、右侧未处理」。等于轴的键被扫到左或右，下一层还会再比较它们。若输入全相等，\\(q=1\\) 或 \\(q=n\\)，与已排序固定轴同一退化。缺口不是再抛一次硬币，而是荷兰国旗式的三段：扫描中维护 $\\lt \\(、\\)=\\(、\\)\\gt $ 三个区间，等于段不再递归。</p><p>随机轴仍在：期望分析把「等于」从比较次数里减掉，重复越多越快，与两路相反。本课仍在比较模型；不启用计数排序。</p><h3 id="三路不是「再开一个等于数组」" tabindex="-1">三路不是「再开一个等于数组」 <a class="header-anchor" href="#三路不是「再开一个等于数组」" aria-label="Permalink to &quot;三路不是「再开一个等于数组」&quot;">​</a></h3><p>就地交换即可。Dijkstra 的荷兰国旗是三段着色；Bentley–McIlroy 在工程里用双指针从两端收等于键，减少交换。本课认三段语义，不把某一份 <code>qsort</code> 抄成词条。</p><p><span class="marginnote">Hoare 的两路是上一课。Dijkstra 1976 把三段写成最严格的循环不变式。Bentley–McIlroy 1993 说明为何标准库排序必须处理重复。CLRS 第 7 章把相等键列为练习级缺口，本课收进主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选轴（随机或三数取中）。一次扫描把数组排成 \\(A[L..q-1]\\lt x\\)、\\(A[q..t]=x\\)、\\(A[t+1..R]\\gt x\\)。递归 \\((L,q-1)\\) 与 \\((t+1,R)\\)。正确性：中段已在最终位置。代价：无重复时与两路同阶；全相等时 \\(\\Theta(n)\\) 结束。</p>',11)),(e(),s(p,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%22%5D%20--%3E%20P3%5B%22%E4%B8%89%E8%B7%AF%E5%88%86%E5%8C%BA%22%5D%0A%20%20P3%20--%3E%20LT%5B%22%E9%80%92%E5%BD%92%20%EF%BC%9C%20%E8%BD%B4%22%5D%0A%20%20P3%20--%3E%20EQ%5B%22%3D%20%E8%BD%B4%EF%BC%9A%E9%92%89%E6%AD%BB%22%5D%0A%20%20P3%20--%3E%20GT%5B%22%E9%80%92%E5%BD%92%20%3E%20%E8%BD%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>稳定性仍默认没有：交换打乱等于键的原次序。要稳定，退回归并，不要在三路上假装。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息论：重复键的排列数小于 \\(n!\\)，比较下界可以低于 \\(n\\log n\\)。三路接近这个松弛；两路不利用。后课下界仍对<strong>互异键</strong>说话，本课先把重复从最坏路径上拿掉。</p><p>与<a href="/cs/select-kth">选择第 k 小</a>：三路给出轴的一段秩，选择可以一次跳过整个等于段。本课不把选择写完。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(\\Omega(n\\log n)\\)，不引入基数。最坏互异键加劣轴仍平方；随机或保险轴仍要。也不处理多键（先比第一关键字再比第二）的整套 MSD。后课默认：快排在重复键上走三路；比较排序的下界下一课对互异键收回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三路把等于轴的键一次钉死，只递归严格两端。</li><li>重复从退化变成线性收束；默认仍不稳。</li><li>互异键的下界仍是下一课的对象。</li><li>出处：Dijkstra, 1976；Bentley and McIlroy, 1993；CLRS 第 7 章。</li></ul>',8))])}const D=i(h,[["render",_]]);export{k as __pageData,D as default};
